/** Synthetic-only merchant benchmark. No row describes a real merchant or live website. */
export type BenchmarkSeverity = 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW';
export type BenchmarkScenario = Readonly<{
  id: string;
  category: string;
  customerQuestion: string;
  previousMessages: readonly Readonly<{ role: 'user' | 'assistant'; content: string }>[];
  requiredKnowledgeOrTool: string;
  authoritativeEvidence: readonly Readonly<{ sourceId: string; type: 'WEBSITE' | 'SHOPIFY_SNAPSHOT' | 'SESSION' | 'AUTHORIZATION'; text: string; freshness?: string; tenantId?: string }>[];
  expectedFactualOutcome: string;
  expectedConversationalBehavior: string;
  failureConditions: readonly string[];
  severity: BenchmarkSeverity;
}>;

