/** Every case gets explicit synthetic evidence and observable expected/failure outcomes. */
export const CARTEIO_QUALITY_BENCHMARK_V1: readonly BenchmarkScenario[] = Object.freeze(seeds.map(([id, category, _language, customerQuestion, expectedFactualOutcome, expectedConversationalBehavior, failure, severity = 'MEDIUM', previousMessages = [], evidenceKeys = [], tool = 'search_business_knowledge']) => Object.freeze({
  id: `cq01.${id}`,
  category,
  customerQuestion,
  previousMessages: Object.freeze(previousMessages),
  requiredKnowledgeOrTool: tool,
  authoritativeEvidence: Object.freeze(evidenceKeys.map((key) => syntheticSources[key])),
  expectedFactualOutcome,
  expectedConversationalBehavior: `${_language}: ${expectedConversationalBehavior}`,
  failureConditions: Object.freeze([failure]),
  severity,
})));

/** Real-merchant runs must provide these approvals and sources; synthetic fixtures are not a substitute. */
export type MerchantBenchmarkApproval = Readonly<{
  merchantId: string;
  testWebsite: string;
  approvedSourceIds: readonly string[];
  approvedSourceFacts: readonly Readonly<{ sourceId: string; exactFact: string; effectiveAt?: string; expiresAt?: string }> [];
  approvedBy: string;
  approvedAt: string;
  permittedTestSession: string;
}>;
